'use strict';
function enhanceAVModels(models,port,stereo){
 Object.assign(models,videoModels,extraModels);
 models.vmgo2.exclusiveOutputs=['analog','usb'];
 models.fx30.note+=' 写真はボディ。';
 let miniIn=(id,label)=>port(id,label,'in','MINI','stereo_line',{accept:['stereo_line','stereo_mic'],channels:2});
 for(let m of Object.values(models)){
  if(m.category==='switcher'){
   let ports=[];
   if(m.name.startsWith('ATEM Mini')||m.name.startsWith('ATEM SDI')){
    if(m.name.includes('G2'))ports=[...['1','2'].map(c=>port('audio'+c,'AUDIO '+c+' MIC/LINE','in','COMBO','line',{accept:['line','mic']})),port('audiophones','PHONES 6.35mm','out','HEADPHONE','headphone')];
    else{ports=[miniIn('audio1','MIC/LINE 1 · 3.5mm'),miniIn('audio2','MIC/LINE 2 · 3.5mm')];if(m.name.includes('Extreme'))ports.push(port('audiophones','PHONES 3.5mm','out','HEADPHONE','headphone'))}
   }else if(m.name.includes('Television Studio'))ports=[...stereo('audio','AUDIO IN XLR','in','XLR'),...stereo('rca','AUDIO IN RCA','in','RCA'),...stereo('main','MAIN OUT','out','TRS'),...stereo('monitor','MONITOR OUT','out','TRS')];
   else if(m.name.includes('Constellation')){ports=stereo('audio','AUDIO IN','in','TRS');if(m.name.includes('4 M/E')||m.name==='ATEM Constellation 8K')ports.push(...stereo('audioout','AUDIO OUT','out','TRS'))}
   else if(m.name==='V-1HD')ports=[...stereo('audio','AUDIO IN RCA','in','RCA'),port('mic','MIC 3.5mm','in','MINI','stereo_mic'),...stereo('audioout','AUDIO OUT RCA','out','RCA'),port('audiophones','PHONES 3.5mm','out','HEADPHONE','headphone')];
   else if(m.name==='VR-4HD')ports=[...Array.from({length:4},(_,i)=>port('audio'+(i+1),'AUDIO '+(i+1)+' MIC/LINE','in','COMBO','line',{accept:['line','mic']})),...stereo('rca','AUDIO 5/6 RCA','in','RCA'),miniIn('mini','AUDIO 7/8 · 3.5mm'),...stereo('main','MAIN OUT XLR','out','XLR'),...stereo('mainrca','MAIN OUT RCA','out','RCA'),...stereo('aux','AUX OUT RCA','out','RCA'),port('audiophones','PHONES 3.5mm','out','HEADPHONE','headphone')];
   m.ports.push(...ports);m.visible.push(...ports.filter(p=>p.dir==='in').slice(0,2).map(p=>p.id));
   for(let p of m.ports)if(['video','uvc'].includes(p.signal))p.embeddedAudio={channels:p.type==='SDI'&&p.dir==='out'&&/Television|Constellation/.test(m.name)?16:2,sampleRate:48000};
   m.note=m.note.replace('音声専用端子は対象外。','').replace('アナログ映像・音声端子は対象外。','アナログ映像は対象外。')+' 音声入力のMIC/LINE切替・内部ミックス・AFVは実機で設定。HDMI / SDI / USB映像には音声も重畳します。';
   m.audioInfo={sampleRate:48000,analogInputs:ports.filter(p=>p.dir==='in').length,analogOutputs:ports.filter(p=>p.dir==='out'&&p.signal==='line').length};
  }
  if(m.category==='computer')for(let p of m.ports)if(p.type==='UVC'){p.accept=['uvc','usb_audio'];p.label=p.label.replace('CAPTURE','MEDIA')}
 }
 for(let key of ['v_a6400','v_hero12']){let m=models[key];m.ports.push(port('mic','MIC 3.5mm','in','MINI','stereo_mic'));m.visible.push('mic')}
 // The FX6 and Z150 audio input blocks are mono XLR, distinct from headphone outputs.
 let z=models.v_z150;z.ports.push(...[1,2].map(i=>port('audio'+i,'INPUT '+i+' MIC/LINE','in','XLR','line',{accept:['line','mic']})));z.visible.push('audio1','audio2');
}
